# Confirm that this is the package root
stopifnot(
  file.exists("DESCRIPTION"),
  file.exists("R/rank-graduation.R"),
  file.exists("R/curves.R")
)

# Remove the old manually created documentation files
rd_files <- list.files(
  "man",
  pattern = "\\.Rd$",
  full.names = TRUE
)

print(rd_files)

if (length(rd_files) > 0L) {
  file.remove(rd_files)
}

# Generate fresh documentation from the roxygen comments
devtools::document()

# Confirm that the files are now generated by roxygen2
print(readLines("man/rga.Rd", n = 2))

stopifnot(
  any(
    grepl(
      "neutral rank-discrimination benchmark",
      readLines("man/rga.Rd"),
      fixed = TRUE
    )
  ),
  any(
    grepl(
      "Plot all four curves",
      readLines("man/rg_curves.Rd"),
      fixed = TRUE
    )
  )
)

# Preview and validate the development version
devtools::load_all(reset = TRUE)
devtools::run_examples()
devtools::test()
devtools::check()

# Install the corrected package
devtools::install(
  upgrade = FALSE,
  dependencies = FALSE,
  build_vignettes = FALSE
)